    for (let i = 0; i < n; i++) {
      const th = rnd(TAU), y = rnd(o.upMax ?? 0.9, o.upMin ?? -0.1), h = Math.sqrt(Math.max(0, 1 - y * y)), sp = speed * rnd(1.2, 0.5);
