  const p = [DOME_C[0] + DOME_R[0] * Math.cos(el) * Math.sin(az), DOME_C[1] + DOME_R[1] * Math.sin(el), DOME_C[2] + DOME_R[2] * Math.cos(el) * Math.cos(az)];
